import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DEqXEGcv.js";const u=JSON.parse('{"title":"Arc FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),n={name:"faq.md"};function i(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="arc-faq" tabindex="-1">Arc FAQ <a class="header-anchor" href="#arc-faq" aria-label="Permalink to &quot;Arc FAQ&quot;">​</a></h1><h2 id="why-another-programming-language" tabindex="-1">Why another programming language? <a class="header-anchor" href="#why-another-programming-language" aria-label="Permalink to &quot;Why another programming language?&quot;">​</a></h2><p>Arc isn&#39;t for humans writing code in editors. It&#39;s for <strong>AI agents generating and consuming code</strong>. When you pay per token, syntax overhead matters. Arc eliminates the ceremony that traditional languages require — imports, async/await boilerplate, error handling scaffolding, API client setup — because AI agents don&#39;t need it.</p><h2 id="how-is-this-different-from-python-or-javascript" tabindex="-1">How is this different from Python or JavaScript? <a class="header-anchor" href="#how-is-this-different-from-python-or-javascript" aria-label="Permalink to &quot;How is this different from Python or JavaScript?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Python/JS</th><th>Arc</th></tr></thead><tbody><tr><td>API calls</td><td>Import library, create client, serialize, deserialize</td><td><code>@GET &quot;url&quot;</code> — one line</td></tr><tr><td>Error handling</td><td>try/catch blocks</td><td>Map-based results with <code>if/el</code></td></tr><tr><td>Async</td><td>async/await keywords everywhere</td><td>Auto-await by default</td></tr><tr><td>Data transformation</td><td>Method chains or nested calls</td><td><code>|&gt;</code> pipeline operator</td></tr><tr><td>Pattern matching</td><td>if/elif/else chains (Python), switch (JS)</td><td><code>match</code> with destructuring</td></tr><tr><td>Token cost</td><td>~100 tokens for typical agent task</td><td>~50 tokens for the same task</td></tr></tbody></table><p>Arc is a <strong>domain-specific language</strong> for AI agent workflows, not a general-purpose replacement.</p><h2 id="can-i-use-this-in-production" tabindex="-1">Can I use this in production? <a class="header-anchor" href="#can-i-use-this-in-production" aria-label="Permalink to &quot;Can I use this in production?&quot;">​</a></h2><p>Arc is in <strong>active development</strong> (Phase 6: Community &amp; Adoption). The interpreter, compiler (with optimizer and JS/WAT codegen), 27 stdlib modules, LSP, VS Code extension, package manager, formatter, linter, and security sandbox are all working with 1,291+ tests passing. Follow the <a href="https://github.com/kai-builds-ai/arc-lang/blob/main/ROADMAP.md" target="_blank" rel="noreferrer">roadmap</a> for status.</p><h2 id="how-do-tool-calls-work" tabindex="-1">How do tool calls work? <a class="header-anchor" href="#how-do-tool-calls-work" aria-label="Permalink to &quot;How do tool calls work?&quot;">​</a></h2><p>Tool calls use the <code>@</code> prefix to invoke external APIs and tools as first-class language constructs:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let user = @GET &quot;api/users/123&quot;              # HTTP GET</span></span>\n<span class="line"><span>@POST &quot;api/messages&quot; {text: &quot;hello&quot;}          # HTTP POST with body</span></span>\n<span class="line"><span>let answer = @llm(&quot;Summarize this: {text}&quot;)   # Custom tool</span></span></code></pre></div><p>The runtime resolves <code>@GET</code>/<code>@POST</code> to HTTP calls and <code>@toolname</code> to registered tool handlers. No imports, no client initialization, no serialization code. The interpreter handles it.</p><h2 id="what-s-the-token-efficiency-claim-based-on" tabindex="-1">What&#39;s the token efficiency claim based on? <a class="header-anchor" href="#what-s-the-token-efficiency-claim-based-on" aria-label="Permalink to &quot;What&#39;s the token efficiency claim based on?&quot;">​</a></h2><p>We measure using GPT-4&#39;s tokenizer (cl100k_base) across common agent programming patterns:</p><ul><li><strong>Function definitions:</strong> ~50% fewer tokens than JS</li><li><strong>API calls:</strong> ~65% fewer tokens</li><li><strong>Error handling:</strong> ~75% fewer tokens</li><li><strong>Pattern matching:</strong> ~40% fewer tokens</li><li><strong>Overall average across agent code:</strong> ~53% reduction</li></ul><p>See the <a href="https://github.com/kai-builds-ai/arc-lang/blob/main/spec/grammar.md#token-counting-methodology" target="_blank" rel="noreferrer">grammar spec</a> for the full methodology and comparison table.</p><h2 id="what-does-el-mean" tabindex="-1">What does <code>el</code> mean? <a class="header-anchor" href="#what-does-el-mean" aria-label="Permalink to &quot;What does `el` mean?&quot;">​</a></h2><p><code>el</code> is Arc&#39;s keyword for <code>else</code>. It saves 2 characters per use and is unambiguous in context:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let x = if ready { &quot;go&quot; } else { &quot;wait&quot; }</span></span></code></pre></div><h2 id="how-do-i-contribute" tabindex="-1">How do I contribute? <a class="header-anchor" href="#how-do-i-contribute" aria-label="Permalink to &quot;How do I contribute?&quot;">​</a></h2><p>See <a href="https://github.com/kai-builds-ai/arc-lang/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>. We welcome contributions from both AI agents and human developers.</p>',21)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
